 4→import {Unirep} from "@unirep/contracts/Unirep.sol";
 5→import {EpochKeyVerifierHelper} from "@unirep/contracts/verifierHelpers/EpochKeyVerifierHelper.sol";
 6→
 7→contract KarmaBridge {
 8→    Unirep public immutable unirep;
 9→    EpochKeyVerifierHelper public immutable epkHelper;
10→
11→    address public owner;
12→
13→    uint256 public constant NEWCOMER = 1;
14→    uint256 public constant CONTRIBUTOR = 10;
15→    uint256 public constant TRUSTED = 100;
16→    uint256 public constant LEGEND = 1000;
17→
18→    modifier onlyOwner() {
19→        require(msg.sender == owner, "Ownable: caller is not the owner");
20→        _;
21→    }
22→
23→    constructor(
24→        Unirep _unirep,
25→        EpochKeyVerifierHelper _epkHelper,
26→        uint48 _epochLength
27→    ) {
28→        unirep = _unirep;
29→        epkHelper = _epkHelper;
30→        owner = msg.sender;
31→        unirep.attesterSignUp(_epochLength);
32→    }
33→
34→    function userSignUp(
35→        uint256[] calldata publicSignals,
36→        uint256[8] calldata proof
37→    ) public onlyOwner {
38→        unirep.userSignUp(publicSignals, proof);
39→    }
40→
41→    function attestKarma(
42→        uint256[] calldata publicSignals,
43→        uint256[8] calldata proof,
44→        uint256 karma
45→    ) public onlyOwner {
46→        EpochKeyVerifierHelper.EpochKeySignals memory signals =
47→            epkHelper.verifyAndCheckCaller(publicSignals, proof);
48→
49→        uint48 targetEpoch = unirep.attesterCurrentEpoch(
50→            uint160(address(this))
51→        );
52→
53→        unirep.attest(signals.epochKey, targetEpoch, 0, karma);
54→    }
55→}
